typedef struct {
    const char *symbol;
    Tree *node;
} Entry;
static void stack_push(Entry **stack, int *n, int *capacity, Entry entry) {
    (*stack)[(*n)++] = entry;
}
static void step_add(Parse *out, Step step) {
    out->steps[out->nsteps++] = step;
}
